@layer components {
  /* Empty: a centered state with an icon in a circle, a title, a description, and actions. */
  [data-slot="empty"] {
    align-items: center;
    border-radius: var(--vh-radius);
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    justify-content: center;
    min-width: 0;
    padding: 1.25rem;
    position: relative;
    text-align: center;
  }

  @media (min-width: 40rem) {
    [data-slot="empty"] {
      padding: 1.5rem;
    }
  }

  @media (min-width: 64rem) {
    [data-slot="empty"] {
      padding: 2rem;
    }
  }

  [data-slot="empty"][data-variant="outline"] {
    background: var(--vh-bg);
    box-shadow: 0 0 0 1px var(--vh-border);
  }

  [data-slot="empty-header"] {
    align-items: center;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    max-width: 24rem;
  }

  [data-slot="empty-media"] {
    align-items: center;
    background: var(--vh-bg-muted);
    border-radius: 9999px;
    color: var(--vh-muted);
    display: inline-flex;
    font-size: 1.25rem;
    height: 2.5rem;
    justify-content: center;
    margin-bottom: 0.25rem;
    width: 2.5rem;
  }

  [data-slot="empty-media"] > svg {
    height: 1em;
    width: 1em;
  }

  [data-slot="empty"][data-size="xs"] [data-slot="empty-media"] {
    font-size: 1rem;
    height: 2rem;
    width: 2rem;
  }

  [data-slot="empty"][data-size="sm"] [data-slot="empty-media"] {
    font-size: 1.125rem;
    height: 2.25rem;
    width: 2.25rem;
  }

  [data-slot="empty-title"] {
    font-size: 1rem;
    font-weight: 500;
    line-height: 1.5rem;
    margin: 0;
    text-wrap: pretty;
  }

  [data-slot="empty-description"] {
    color: var(--vh-muted);
    font-size: 0.875rem;
    line-height: 1.25rem;
    margin: 0;
    text-wrap: balance;
  }

  [data-slot="empty"]:is([data-size="xs"], [data-size="sm"]) [data-slot="empty-title"] {
    font-size: 0.875rem;
    line-height: 1.25rem;
  }

  [data-slot="empty"]:is([data-size="xs"], [data-size="sm"]) [data-slot="empty-description"] {
    font-size: 0.75rem;
    line-height: 1rem;
  }

  [data-slot="empty-content"] {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    justify-content: center;
    margin-top: 0.5rem;
    max-width: 24rem;
  }
}

export { default as Empty } from "./Empty.vue";
export { default as EmptyContent } from "./EmptyContent.vue";
export { default as EmptyDescription } from "./EmptyDescription.vue";
export { default as EmptyHeader } from "./EmptyHeader.vue";
export { default as EmptyMedia } from "./EmptyMedia.vue";
export { default as EmptyTitle } from "./EmptyTitle.vue";
export type * from "./types.ts";

export type EmptySize = "xs" | "sm" | "md";
export type EmptyVariant = "ghost" | "outline";

export interface EmptyProps {
  size?: EmptySize;
  variant?: EmptyVariant;
}

export interface EmptySlots {
  default?: () => unknown;
}

export interface EmptyHeaderSlots {
  default?: () => unknown;
}

export interface EmptyMediaSlots {
  default?: () => unknown;
}

export interface EmptyTitleSlots {
  default?: () => unknown;
}

export interface EmptyDescriptionSlots {
  default?: () => unknown;
}

export interface EmptyContentSlots {
  default?: () => unknown;
}
